// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzNumber) public {
        vm.assume(fuzzNumber > 0 && fuzzNumber <= 1_000_000);
        vm.roll(fuzzNumber);
        vm.warp(1);
        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "setup call failed");
        bool expectedZero = (block.number % 15 == 0);
        bool actuallyZero = (address(c).balance == 0);
        assertTrue(expectedZero == actuallyZero);
    }
}
